package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen0Test {

    @Test
    public void testFormData_EmptyList() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_FormControlWithNoName() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("type", "text"));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_FormControlWithNameButNoValue() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("name", "test"));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_FormControlWithNameAndValue() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("name", "test", "value", "hello"));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key);
        assertEquals("hello", result.get(0).value);
    }

    @Test
    public void testFormData_FormControlWithNameAndChecked() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("name", "test", "type", "checkbox", "checked", ""));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key);
        assertEquals(element.val(), result.get(0).value);
    }

    @Test
    public void testFormData_FormControlWithNameAndSelected() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element select = new Element(new Tag("select"), "", new Attributes("name", "test"));
        Element option = new Element(new Tag("option"), "", new Attributes("selected", ""));
        select.appendChild(option);
        form.addElement(select);
        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key);
        assertEquals(option.val(), result.get(0).value);
    }

    @Test
    public void testFormData_FormControlWithNameAndSelectedButNoValue() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element select = new Element(new Tag("select"), "", new Attributes("name", "test"));
        Element option = new Element(new Tag("option"), "", new Attributes("selected", ""));
        select.appendChild(option);
        form.addElement(select);
        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key);
        assertEquals("", result.get(0).value);
    }

    @Test
    public void testFormData_FormControlWithNameButNoTypeNorValueNorChecked() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("name", "test"));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertEquals(1, result.size());
        assertEquals("test", result.get(0).key);
        assertEquals(element.val(), result.get(0).value);
    }

    @Test
    public void testFormData_FormControlWithNameAndTypeCheckboxButNoValueNorChecked() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("name", "test", "type", "checkbox"));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_FormControlWithNameAndTypeRadioButNoValueNorChecked() {
        FormElement form = new FormElement(new Tag("form"), "", new Attributes());
        Element element = new Element(new Tag("input"), "", new Attributes("name", "test", "type", "radio"));
        form.addElement(element);
        List<Connection.KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }
}
